app/globals.css:
@import "tailwindcss";

:root {
  --ink: #efe9df;
  --muted: #8d8578;
  --line: rgba(239, 233, 223, 0.16);
  --amber: #c99555;
  --bg: #0a0a08;
}

* { box-sizing: border-box; }
html { background: var(--bg); scroll-behavior: auto; }
body {
  margin: 0;
  min-height: 100%;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
a { color: inherit; text-decoration: none; }
.experience-canvas {
  position: fixed;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100svh;
}
.hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 72px;
  padding: 0 32px;
  border-bottom: 1px solid var(--line);
  mix-blend-mode: difference;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.11em;
}
.identity { display: flex; align-items: center; gap: 12px; }
.identity span { color: #aaa39a; }
.chapter-meter { display: flex; align-items: center; gap: 10px; color: #bbb4aa; }
.chapter-meter i { width: 42px; height: 1px; background: rgba(255,255,255,.45); }
.hud nav { justify-self: end; display: flex; gap: 20px; color: #aaa39a; }
.story-space { position: relative; z-index: 2; pointer-events: none; }
.scroll-chapter { height: 100vh; }
.scroll-chapter:first-child { height: 120vh; }
.scroll-chapter > span { position: absolute; opacity: 0; pointer-events: none; }
.chapter-copy {
  position: fixed;
  z-index: 10;
  left: clamp(24px, 7vw, 120px);
  bottom: clamp(50px, 9vh, 120px);
  width: min(720px, calc(100vw - 48px));
  pointer-events: none;
  text-shadow: 0 2px 32px rgba(0,0,0,.32);
}
.chapter-copy > p:first-child {
  margin: 0 0 16px;
  color: #b7a589;
  font: 500 11px/1 ui-monospace, monospace;
  letter-spacing: .18em;
}
.chapter-copy h1 {
  margin: 0;
  font-size: clamp(4rem, 10vw, 10rem);
  font-weight: 300;
  letter-spacing: -.075em;
  line-height: .8;
}
.chapter-copy h2 {
  max-width: 620px;
  margin: 18px 0 0;
  color: #c7c0b6;
  font-size: clamp(.95rem, 1.5vw, 1.25rem);
  font-weight: 400;
}
.chapter-copy .meaning {
  max-width: 550px;
  margin: 18px 0 0;
  color: #8e887f;
  font-size: 13px;
  line-height: 1.7;
}
.noscript { position: relative; z-index: 100; padding: 2rem; }
@media (max-width: 760px) {
  .hud { grid-template-columns: 1fr auto; padding: 0 18px; }
  .chapter-meter { display: none; }
  .hud nav { gap: 12px; }
  .identity span { display: none; }
  .chapter-copy { left: 22px; bottom: 50px; }
  .chapter-copy h1 { font-size: clamp(4rem, 21vw, 7.2rem); }
}
@media (prefers-reduced-motion: reduce) {
  .story-space { scroll-behavior: auto; }
}

.quick-profile-trigger {
  position: fixed;
  z-index: 24;
  top: 86px;
  right: 28px;
  border: 1px solid var(--line);
  background: rgba(10, 10, 8, 0.56);
  color: #cfc6b9;
  padding: 10px 13px;
  font: 500 10px/1 ui-monospace, monospace;
  letter-spacing: .13em;
  backdrop-filter: blur(14px);
  cursor: pointer;
}
.quick-profile-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  background: rgba(0,0,0,.48);
  backdrop-filter: blur(5px);
}
.quick-profile {
  position: absolute;
  inset: 0 0 0 auto;
  width: min(620px, 100%);
  overflow: auto;
  padding: 72px 46px 52px;
  background: #11100d;
  border-left: 1px solid var(--line);
  box-shadow: -36px 0 100px rgba(0,0,0,.35);
}
.quick-profile-close {
  position: absolute;
  top: 22px;
  right: 26px;
  border: 0;
  background: transparent;
  color: #d8d0c5;
  font-size: 28px;
  cursor: pointer;
}
.ui-kicker {
  color: #ad9778;
  font: 500 10px/1 ui-monospace, monospace;
  letter-spacing: .16em;
}
.quick-profile h2 {
  margin: 10px 0 4px;
  font-size: clamp(3rem, 7vw, 5.4rem);
  font-weight: 300;
  letter-spacing: -.06em;
}
.profile-role { color: #968e83; }
.quick-profile section {
  margin-top: 38px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}
.quick-profile h3 {
  margin: 0 0 16px;
  color: #c3b9aa;
  font: 500 11px/1 ui-monospace, monospace;
  letter-spacing: .13em;
  text-transform: uppercase;
}
.profile-row {
  display: grid;
  grid-template-columns: 145px 1fr;
  gap: 4px 18px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,.055);
}
.profile-row span {
  grid-row: 1 / span 2;
  color: #766e64;
  font: 400 10px/1.4 ui-monospace, monospace;
}
.profile-row strong { font-size: 13px; font-weight: 500; }
.profile-row em { color: #777169; font-size: 12px; font-style: normal; }
.profile-system {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  padding: 9px 0;
  border-bottom: 1px solid rgba(255,255,255,.05);
}
.profile-system span {
  color: #796d5d;
  font: 400 9px/1 ui-monospace, monospace;
  text-transform: uppercase;
}
.profile-system strong { font-size: 12px; font-weight: 500; }
.profile-links {
  display: flex;
  gap: 22px;
  margin-top: 36px;
  font: 500 11px/1 ui-monospace, monospace;
  letter-spacing: .08em;
}
.chapter-nav {
  position: fixed;
  z-index: 12;
  top: 50%;
  right: 22px;
  display: grid;
  gap: 8px;
  transform: translateY(-50%);
  pointer-events: none;
}
.chapter-nav-item {
  position: relative;
  display: grid;
  grid-template-columns: 25px auto;
  align-items: center;
  gap: 8px;
  min-height: 16px;
  color: #5f5a52;
  font: 400 8px/1 ui-monospace, monospace;
}
.chapter-nav-item b {
  opacity: 0;
  transform: translateX(4px);
  font-weight: 400;
  white-space: nowrap;
  transition: opacity .2s ease, transform .2s ease, color .2s ease;
}
.chapter-nav-active {
  position: absolute;
  right: -7px;
  width: 2px;
  height: 16px;
  background: #c99a5b;
  box-shadow: 0 0 14px rgba(201,154,91,.45);
}
.chapter-nav-item:has(.chapter-nav-active) { color: #cbb89c; }
.chapter-nav-item:has(.chapter-nav-active) b { opacity: 1; transform: none; color: #bcb1a3; }
.inspection-shell {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 30px;
  background: rgba(7,7,6,.7);
  backdrop-filter: blur(18px);
  color: var(--ink);
  pointer-events: auto;
}
.inspection-back {
  position: absolute;
  top: 28px;
  left: 28px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.02);
  color: #c9c0b3;
  padding: 10px 13px;
  font: 500 10px/1 ui-monospace, monospace;
  letter-spacing: .1em;
  cursor: pointer;
}
.inspection-content {
  width: min(720px, 100%);
}
.inspection-content > p:first-child {
  color: #aa916f;
  font: 500 10px/1 ui-monospace, monospace;
  letter-spacing: .16em;
}
.inspection-content h2 {
  margin: 14px 0;
  font-size: clamp(3rem, 8vw, 7rem);
  font-weight: 300;
  letter-spacing: -.06em;
}
.inspection-content p:last-child {
  max-width: 600px;
  color: #8e867b;
  line-height: 1.7;
}
@media (max-width: 900px) {
  .chapter-nav { display: none; }
  .quick-profile-trigger { top: auto; bottom: 18px; right: 18px; }
  .quick-profile { padding: 68px 24px 40px; }
  .profile-row { grid-template-columns: 1fr; }
  .profile-row span { grid-row: auto; }
}

.artifact-inspector {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 28px;
  background: rgba(6,6,5,.66);
  backdrop-filter: blur(16px);
}
.artifact-inspector-panel {
  position: relative;
  width: min(900px, 100%);
  min-height: min(640px, 78vh);
  padding: clamp(72px, 9vw, 110px) clamp(26px, 6vw, 72px) 48px;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 80% 0%, rgba(201,154,91,.09), transparent 30%),
    #11100d;
  box-shadow: 0 40px 120px rgba(0,0,0,.5);
}
.artifact-inspector-panel h2 {
  margin: 16px 0 20px;
  font-size: clamp(3.5rem, 10vw, 9rem);
  font-weight: 300;
  line-height: .86;
  letter-spacing: -.07em;
}
.artifact-inspector-panel > p:last-child {
  max-width: 650px;
  color: #8d857a;
  line-height: 1.75;
}
